5	/**
6	 * Derives fiscal-year values from a date. The fiscal year starts on 1 July, so a date in July
7	 * through December belongs to the fiscal year that ends in the following calendar year, while a
8	 * date in January through June belongs to the fiscal year ending in its own calendar year. Fiscal
9	 * years are numbered by the calendar year they end in (e.g. 1 July 2026 through 30 June 2027 is
10	 * fiscal year 2027, labelled {@code FY27}).
11	 */
12	public final class FiscalYear {
13	
14	    /** Month (1-12) on whose first day the fiscal year begins. */
15	    private static final int FISCAL_YEAR_START_MONTH = 7;
16	
17	    private FiscalYear() {
18	    }
19	
20	    /** The fiscal year {@code date} falls in, numbered by the calendar year it ends in. */
21	    public static int yearOf(LocalDate date) {
22	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
23	    }
24	
25	    /** The {@code FY<YY>} label for {@code date}, where {@code YY} is the last two digits of its
26	     *  fiscal year, zero-padded (e.g. {@code FY27}). */
27	    public static String labelOf(LocalDate date) {
28	        return String.format("FY%02d", yearOf(date) % 100);
29	    }
30	
31	    /** The number of whole fiscal years elapsed from {@code from} to {@code to}, i.e. the fiscal
32	     *  year of {@code to} minus the fiscal year of {@code from}. */
33	    public static int elapsedYears(LocalDate from, LocalDate to) {
34	        return yearOf(to) - yearOf(from);
35	    }
36	}
