3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality} (region). The postcode is preferred: a present,
7	 * well-formed postcode is matched against each region's fixed range (NSW 2000-2099,
8	 * VIC 3000-3099, QLD 4000-4099). Only when the postcode is absent or falls in no known
9	 * range does derivation fall back to a fixed city-to-region table. Anything the postcode
10	 * and city both fail to place derives the locality {@code "UNKNOWN"}.
11	 */
12	public final class LocalityResolver {
13	
14	    /** City -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW",
17	            "Melbourne", "VIC",
18	            "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_RANGE = Map.of(
22	            "NSW", new int[] {2000, 2099},
23	            "VIC", new int[] {3000, 3099},
24	            "QLD", new int[] {4000, 4099});
25	
26	    /** Region -> IANA timezone name. */
27	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
28	            "NSW", "Australia/Sydney",
29	            "VIC", "Australia/Melbourne",
30	            "QLD", "Australia/Brisbane");
31	
32	    /** The locality returned when neither postcode nor city places the owner. */
33	    public static final String UNKNOWN = "UNKNOWN";
34	
35	    private LocalityResolver() {
36	    }
37	
38	    /**
39	     * Returns the canonical region for {@code city}, or {@code "UNKNOWN"} when the
40	     * city (including {@code null}) is not in the table.
41	     */
42	    public static String localityOf(String city) {
43	        return CITY_REGION.getOrDefault(city, UNKNOWN);
44	    }
45	
46	    /**
47	     * Returns the canonical region, preferring {@code postcode}: when it is present and
48	     * falls in a known region's range that region wins. Otherwise the {@code city} table
49	     * decides, and failing that the locality is {@code "UNKNOWN"}. This returns the same
50	     * region for known cities but disambiguates cities that share a name.
51	     */
52	    public static String localityOf(String postcode, String city) {
53	        String fromPostcode = regionForPostcode(postcode);
54	        if (fromPostcode != null) {
55	            return fromPostcode;
56	        }
57	        return localityOf(city);
58	    }
59	
60	    /**
61	     * The {@code REGION} component carried by a {@code customerCode} of the form
62	     * {@code <REGION>-<HASH8>}. Now that the customer code embeds the region, the owner's locality
63	     * is read straight back off the identity rather than recomputed from postcode and city.
64	     * Returns {@code "UNKNOWN"} when the code is absent or carries no region component.
65	     */
66	    public static String regionOfCustomerCode(String customerCode) {
67	        if (customerCode == null || customerCode.isBlank()) {
68	            return UNKNOWN;
69	        }
70	        int dash = customerCode.indexOf('-');
71	        if (dash <= 0) {
72	            return UNKNOWN;
73	        }
74	        return customerCode.substring(0, dash);
75	    }
76	
77	    /**
78	     * Whether {@code region} is one of the known regions (NSW, VIC or QLD) rather than
79	     * {@code "UNKNOWN"} or any unrecognised value (including {@code null}).
80	     */
81	    public static boolean isKnownRegion(String region) {
82	        return REGION_TIMEZONE.containsKey(region);
83	    }
84	
85	    /**
86	     * The IANA timezone name for {@code region} via the fixed region-to-timezone table
87	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane).
88	     * Returns {@code null} when the region (including {@code null} or {@code "UNKNOWN"}) is not
89	     * in the table.
90	     */
91	    public static String timezoneOfRegion(String region) {
92	        return REGION_TIMEZONE.get(region);
93	    }
94	
95	    /** The region whose range contains {@code postcode}, or {@code null} when absent/unplaced. */
96	    private static String regionForPostcode(String postcode) {
97	        if (postcode == null || postcode.isBlank()) {
98	            return null;
99	        }
100	        int value;
101	        try {
102	            value = Integer.parseInt(postcode.trim());
103	        }
104	        catch (NumberFormatException ex) {
105	            return null;
106	        }
107	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
108	            int[] range = entry.getValue();
109	            if (value >= range[0] && value <= range[1]) {
110	                return entry.getKey();
111	            }
112	        }
113	        return null;
114	    }
115	}
