3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Immutable structured audit event emitted alongside the human-readable audit line when a new owner
9	 * is created (see {@link AuditOwnerCreated}). Serialized to a single-line JSON object
10	 * {@code {seq, ownerId, customerCode, membershipLevel, event}} where {@code event} is always
11	 * {@value #EVENT}.
12	 *
13	 * <p>{@code seq} is a process-wide, monotonically increasing sequence number handed out by
14	 * {@link #of(Owner, int)} — one per created owner, ordering the events regardless of which request
15	 * produced them.
16	 *
17	 * <p>The event carries the owner's <em>current primary identifier</em>, resolved once by
18	 * {@link #primaryIdentifierOf(Owner)}. Today that is the {@code customerCode}; when the customer
19	 * code is later unified into the {@code memberId}, only that accessor changes and every event then
20	 * carries the {@code memberId} instead — the callers and the serialized shape stay put.
21	 *
22	 * <p>Instances are immutable: all fields are captured at construction and never mutated.
23	 */
24	final class OwnerCreatedEvent {
25	
26	    /** The fixed {@code event} discriminator carried by every owner-created event. */
27	    static final String EVENT = "OWNER_CREATED";
28	
29	    /** Process-wide source of monotonically increasing sequence numbers across all creates. */
30	    private static final AtomicLong SEQUENCE = new AtomicLong();
31	
32	    private final long seq;
33	
34	    private final int ownerId;
35	
36	    private final String primaryIdentifier;
37	
38	    private final int membershipLevel;
39	
40	    private OwnerCreatedEvent(long seq, int ownerId, String primaryIdentifier, int membershipLevel) {
41	        this.seq = seq;
42	        this.ownerId = ownerId;
43	        this.primaryIdentifier = primaryIdentifier;
44	        this.membershipLevel = membershipLevel;
45	    }
46	
47	    /**
48	     * A new event for the just-saved {@code owner} at the given {@code membershipLevel}, drawing the
49	     * next sequence number. The owner must already be persisted so {@link Owner#getId()} is set.
50	     */
51	    static OwnerCreatedEvent of(Owner owner, int membershipLevel) {
52	        return new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
53	                primaryIdentifierOf(owner), membershipLevel);
54	    }
55	
56	    /**
57	     * The owner's current primary identifier. This is the single point that decides which field
58	     * value the event carries: the {@code customerCode} today, and whatever replaces it later.
59	     */
60	    private static String primaryIdentifierOf(Owner owner) {
61	        return owner.getCustomerCode();
62	    }
63	
64	    /** This event as a compact, single-line JSON object. */
65	    String toJson() {
66	        return "{"
67	                + "\"seq\":" + this.seq
68	                + ",\"ownerId\":" + this.ownerId
69	                + ",\"customerCode\":" + quote(this.primaryIdentifier)
70	                + ",\"membershipLevel\":" + this.membershipLevel
71	                + ",\"event\":" + quote(EVENT)
72	                + "}";
73	    }
74	
75	    /** JSON string literal for {@code value}, escaping quotes and backslashes, or {@code null}. */
76	    private static String quote(String value) {
77	        if (value == null) {
78	            return "null";
79	        }
80	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
81	        for (int i = 0; i < value.length(); i++) {
82	            char c = value.charAt(i);
83	            if (c == '"' || c == '\\') {
84	                sb.append('\\');
85	            }
86	            sb.append(c);
87	        }
88	        return sb.append('"').toString();
89	    }
90	}
