3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	
11	/**
12	 * Shared derivation of an owner's {@code identityKey} — the single value that all duplicate detection
13	 * is now expressed through. The key is the lower-case hex SHA-256 digest of
14	 * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}, where:
15	 *
16	 * <ul>
17	 * <li>{@code normalizedTelephone} is the E.164 form (see {@link TelephoneE164});</li>
18	 * <li>{@code lowerEmail} is the lower-cased email, or empty when none is supplied; and</li>
19	 * <li>{@code soundex(lastName)} is the Soundex code of the last name (see {@link Soundex}).</li>
20	 * </ul>
21	 *
22	 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal. Because the telephone is
23	 * part of the key, two owners who share a last name and postcode but carry different telephones have
24	 * different keys and are both allowed (the weaker overlap is a soft match, see
25	 * {@link AssignPossibleDuplicate}). The postcode is not part of the key, so a household is no longer a
26	 * hard-duplicate factor.
27	 */
28	public final class OwnerIdentityKey {
29	
30	    private OwnerIdentityKey() {
31	    }
32	
33	    /**
34	     * Identity key for an incoming create-owner request (after {@link ValidateNewOwner}). The last
35	     * name is taken straight from the request, so the key matches the one the owner will carry once
36	     * saved.
37	     */
38	    public static String forRequest(OwnerFieldsDto request) {
39	        return build(request.getTelephone(), request.getEmail(), request.getLastName());
40	    }
41	
42	    /** Identity key for an existing, stored owner. */
43	    public static String forOwner(Owner owner) {
44	        return build(owner.getTelephone(), owner.getEmail(), owner.getLastName());
45	    }
46	
47	    private static String build(String telephone, String email, String lastName) {
48	        String raw = normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
49	                + Soundex.soundex(lastName);
50	        return sha256hex(raw);
51	    }
52	
53	    /** Lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value} (64 characters). */
54	    private static String sha256hex(String value) {
55	        try {
56	            byte[] digest = MessageDigest.getInstance("SHA-256")
57	                    .digest(value.getBytes(StandardCharsets.UTF_8));
58	            StringBuilder sb = new StringBuilder(digest.length * 2);
59	            for (byte b : digest) {
60	                sb.append(String.format("%02x", b));
61	            }
62	            return sb.toString();
63	        }
64	        catch (NoSuchAlgorithmException ex) {
65	            throw new IllegalStateException("SHA-256 unavailable", ex);
66	        }
67	    }
68	
69	    /** E.164 form when the value can form one, otherwise the raw value so it only matches itself. */
70	    private static String normalizeTelephone(String telephone) {
71	        if (telephone == null) {
72	            return "";
73	        }
74	        try {
75	            return TelephoneE164.normalize(telephone);
76	        }
77	        catch (InvalidTelephoneException ex) {
78	            return telephone;
79	        }
80	    }
81	
82	    /** Lower-cased email, or empty when none is supplied. */
83	    private static String normalizeEmail(String email) {
84	        if (email == null || email.isBlank()) {
85	            return "";
86	        }
87	        return email.trim().toLowerCase();
88	    }
89	}
