5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Scores an owner's {@code membershipPoints} and maps them to a numeric {@code membershipLevel}.
9	 * Points start at 0 and accrue from the owner's factors: +2 when an email is present, +1 when its
10	 * {@code namesakeCount} is 0, +2 for a household of 3 or more members, and +3 when tenure — the
11	 * fiscal years (starting 1 July) elapsed from its {@code registrationDate} to today — exceeds 1.
12	 * The total maps to a level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
13	 *
14	 * <p>The household factor needs the number of owners sharing the household, which only the
15	 * repository knows; {@link #pointsOf(Owner)} scores the owner's own fields with no household bump,
16	 * while {@link #pointsOf(Owner, int)} adds it once the caller supplies the household size.
17	 */
18	public final class MembershipLevel {
19	
20	    /** Points awarded when the owner has an email. */
21	    private static final int EMAIL_POINTS = 2;
22	
23	    /** Points awarded when the owner shares its name with no existing owner. */
24	    private static final int UNIQUE_NAME_POINTS = 1;
25	
26	    /** Points awarded when the owner's household has {@value #HOUSEHOLD_THRESHOLD} or more members. */
27	    private static final int HOUSEHOLD_POINTS = 2;
28	
29	    /** Points awarded when the owner's tenure exceeds {@value #TENURE_FISCAL_YEARS} fiscal years. */
30	    private static final int TENURE_POINTS = 3;
31	
32	    /** Household size, in members, at or above which {@link #HOUSEHOLD_POINTS} is awarded. */
33	    private static final int HOUSEHOLD_THRESHOLD = 3;
34	
35	    /** Tenure, in elapsed fiscal years, that an owner must exceed to earn {@link #TENURE_POINTS}. */
36	    private static final int TENURE_FISCAL_YEARS = 1;
37	
38	    private MembershipLevel() {
39	    }
40	
41	    /** Membership points from the owner's own fields, without the household factor. */
42	    public static int pointsOf(Owner owner) {
43	        return pointsOf(owner, 0);
44	    }
45	
46	    /** Membership points including +2 when {@code householdSize} is 3 or more. */
47	    public static int pointsOf(Owner owner, int householdSize) {
48	        int points = 0;
49	        String email = owner.getEmail();
50	        if (email != null && !email.isEmpty()) {
51	            points += EMAIL_POINTS;
52	        }
53	        Integer namesakeCount = owner.getNamesakeCount();
54	        if (namesakeCount != null && namesakeCount == 0) {
55	            points += UNIQUE_NAME_POINTS;
56	        }
57	        if (householdSize >= HOUSEHOLD_THRESHOLD) {
58	            points += HOUSEHOLD_POINTS;
59	        }
60	        if (exceedsTenure(owner.getRegistrationDate())) {
61	            points += TENURE_POINTS;
62	        }
63	        return points;
64	    }
65	
66	    /** Maps {@code points} to a level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
67	    public static int levelOf(int points) {
68	        if (points <= 1) {
69	            return 1;
70	        }
71	        if (points <= 3) {
72	            return 2;
73	        }
74	        if (points <= 5) {
75	            return 3;
76	        }
77	        return 4;
78	    }
79	
80	    /** Whether more than {@value #TENURE_FISCAL_YEARS} fiscal years have elapsed from
81	     *  {@code registrationDate} to today. */
82	    private static boolean exceedsTenure(LocalDate registrationDate) {
83	        if (registrationDate == null) {
84	            return false;
85	        }
86	        return FiscalYear.elapsedYears(registrationDate, LocalDate.now()) > TENURE_FISCAL_YEARS;
87	    }
88	}
