8	/**
9	 * Assigns the owner's soft-match flags {@code possibleDuplicate} / {@code possibleDuplicateOf}. An
10	 * exact-identity duplicate has already been rejected with 409 by {@link CheckOwnerIdentityUnique}, so
11	 * every owner reaching this step is being created. This step flags the weaker overlap: an owner that
12	 * shares an existing owner's {@link Soundex Soundex code} of the last name and its {@code postcode}
13	 * but carries a <em>different</em> {@code identityKey} (see {@link OwnerIdentityKey}). Because the
14	 * telephone (and email) are part of that key, two owners with the same last name and postcode but a
15	 * different telephone differ in their key and so are flagged here rather than rejected. When such a
16	 * match exists {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the matching
17	 * owner's id (the lowest id when several match, for determinism); otherwise {@code possibleDuplicate}
18	 * is false and {@code possibleDuplicateOf} left absent.
19	 *
20	 * <p>A declared household member (a request with {@code sharesHousehold} true) is <em>not</em> a
21	 * suspected duplicate: it has explicitly declared it shares the household, so its flags are left
22	 * unset.
23	 *
24	 * <p>Runs after {@link BuildOwner} has produced the {@link Owner} and before {@link SaveOwner}
25	 * persists it, so {@link OwnerRepository#findAll()} returns only the pre-existing owners and the new
26	 * owner never matches itself. Mutates the entity in place so {@link SaveOwner} stores the values and
27	 * later reads return them.
28	 */
29	public class AssignPossibleDuplicate {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
32	        if (Household.sharesHousehold(request)) {
33	            // A declared household member is not a suspected duplicate.
34	            owner.setPossibleDuplicate(false);
35	            owner.setPossibleDuplicateOf(null);
36	            return;
37	        }
38	        String postcode = owner.getPostcode();
39	        Integer matchId = null;
40	        if (postcode != null && !postcode.isBlank()) {
41	            String soundex = Soundex.soundex(owner.getLastName());
42	            String identityKey = OwnerIdentityKey.forOwner(owner);
43	            for (Owner other : ownerRepository.findAll()) {
44	                if (other.isDeleted()) {
45	                    continue; // a soft-deleted owner is not a possible-duplicate match
46	                }
47	                if (soundex.equals(Soundex.soundex(other.getLastName()))
48	                        && postcode.equals(other.getPostcode())
49	                        && !identityKey.equals(OwnerIdentityKey.forOwner(other))) {
50	                    if (matchId == null || (other.getId() != null && other.getId() < matchId)) {
51	                        matchId = other.getId();
52	                    }
53	                }
54	            }
55	        }
56	        owner.setPossibleDuplicate(matchId != null);
57	        owner.setPossibleDuplicateOf(matchId);
58	    }
